import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework.B5WAEDB7.js";const p=JSON.parse('{"title":"Embedding a Portal","description":"Embed a published Portal in your own website — inline or as a window.","frontmatter":{"title":"Embedding a Portal","description":"Embed a published Portal in your own website — inline or as a window."},"headers":[],"relativePath":"en/seiten/portal-einbetten.md","filePath":"en/seiten/portal-einbetten.md","lastUpdated":1787319236000}'),n={name:"en/seiten/portal-einbetten.md"};function r(s,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="embedding-a-portal" tabindex="-1">Embedding a Portal <a class="header-anchor" href="#embedding-a-portal" aria-label="Permalink to &quot;Embedding a Portal&quot;">​</a></h1><p>A published Portal can be embedded in your own website. Visitors stay on your page while doing so.</p><p><strong>Requirement:</strong> a <a href="/en/seiten/portal-veroeffentlichen">Portal link</a>. Without one, there&#39;s nothing to embed.</p><h2 id="generating-the-embed-code" tabindex="-1">Generating the embed code <a class="header-anchor" href="#generating-the-embed-code" aria-label="Permalink to &quot;Generating the embed code&quot;">​</a></h2><p>Choose <strong>Embed on your website</strong> in the share dialog. <em>Embed page</em> opens.</p><p>You&#39;ll find the finished code under <em>Embed code</em>. Copy it to the desired spot on your website.</p><h2 id="embedding-style" tabindex="-1">Embedding style <a class="header-anchor" href="#embedding-style" aria-label="Permalink to &quot;Embedding style&quot;">​</a></h2><p>Three options:</p><table tabindex="0"><thead><tr><th>Style</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Inline (on the page)</strong></td><td>The Portal sits fixed in the page flow, like an image or video</td></tr><tr><td><strong>Window (bottom left)</strong></td><td>A button opens the Portal in an overlay window</td></tr><tr><td><strong>Window (bottom right)</strong></td><td>The same, positioned on the right</td></tr></tbody></table><h3 id="inline" tabindex="-1">Inline <a class="header-anchor" href="#inline" aria-label="Permalink to &quot;Inline&quot;">​</a></h3><p>For content that belongs to the page: an overview in a customer area, a sign-up form on an event page, a price list.</p><p>Settings: <strong>Width</strong>, <strong>Height</strong>, and <strong>Auto-adjust height</strong> (<em>The height automatically adjusts to the page content</em>).</p><div class="tip custom-block"><p class="custom-block-title">Turn on auto-adjust height</p><p>Without this option, the embedded Portal gets a fixed height. With expanding sections, tabs, or longer tables, a scrollbar appears inside the frame — hard to use on mobile.</p></div><h3 id="window" tabindex="-1">Window <a class="header-anchor" href="#window" aria-label="Permalink to &quot;Window&quot;">​</a></h3><p>A button at the edge of the screen opens the Portal as an overlay. For things that should always be reachable without dominating the page: feedback, support requests, issue reports.</p><p>Settings: <strong>Button text</strong> (default <em>Feedback</em>) and <strong>Button color</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Choose position based on your layout</p><p><em>Bottom right</em> is the usual spot for help and chat elements — that&#39;s where users expect it. Choose <em>bottom left</em> if a cookie notice, chat widget, or scroll-to-top button already occupies the right.</p></div><h2 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to &quot;Preview&quot;">​</a></h2><p>Use <strong>Preview</strong> to check the result before installing the code.</p><h2 id="what-to-watch-for-on-your-website" tabindex="-1">What to watch for on your website <a class="header-anchor" href="#what-to-watch-for-on-your-website" aria-label="Permalink to &quot;What to watch for on your website&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">The Portal stays independent</p><p>The embedded content comes from ApptiveGrid, not from your server. Practical consequences:</p><ul><li>Your website&#39;s styles <strong>don&#39;t</strong> affect the Portal. Styling happens in the <a href="/en/seiten/seite-erstellen">page settings</a>.</li><li>The Portal link&#39;s access restriction still applies when embedded. If <em>With credentials</em> is set, the login screen appears inside the frame.</li><li>If a visitor&#39;s browser blocks third-party content, the frame stays empty.</li></ul></div><div class="warning custom-block"><p class="custom-block-title">Check your privacy notice</p><p>Embedding loads content from an external service, and visitors may enter personal data into an embedded form. Check whether your privacy policy covers this — especially for a window widget that runs on every page.</p></div><h2 id="common-issues" tabindex="-1">Common issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common issues&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th></tr></thead><tbody><tr><td>Frame stays empty</td><td>No Portal link exists, or it was deleted</td></tr><tr><td>Login screen instead of content</td><td>The link is restricted to <em>With credentials</em></td></tr><tr><td>Scrollbar inside the frame</td><td><em>Auto-adjust height</em> is off</td></tr><tr><td>Cut off on smartphones</td><td>Fixed width in the embed code; use relative width instead</td></tr><tr><td>Portal shows too much data</td><td>The embedded view isn&#39;t filtered enough</td></tr></tbody></table><h2 id="embedding-a-form-instead-of-a-portal" tabindex="-1">Embedding a form instead of a Portal <a class="header-anchor" href="#embedding-a-form-instead-of-a-portal" aria-label="Permalink to &quot;Embedding a form instead of a Portal&quot;">​</a></h2><p>Forms have their own embedding path with similar settings. For pure data collection, that&#39;s the more direct route.</p><p>→ <a href="/en/formulare/formular-teilen">Sharing a form</a></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/seiten/portal-veroeffentlichen">Publishing a Portal</a></li><li><a href="/en/zusammenarbeit/zugriff-beschraenken">Access to shared content</a></li><li><a href="/en/seiten/seitenlayout">Page layout</a></li></ul>',29)])])}const b=t(n,[["render",r]]);export{p as __pageData,b as default};
